/**
 * The MET Norway failover forecast (mukoko-dev/mukoko-weather#434) as the app
 * receives it: `X-Weather-Provider: met-no` and a payload converted by the
 * forecast Worker (`weather_core::met_no`). The golden file is that payload
 * for the real MET Norway response of Sembawang, Singapore, fetched
 * 2026-11-02 (`tests/fixtures/met-no-forecast-singapore.json`, regenerated by
 * the Rust test of the same name). It must behave as a live forecast that is
 * kept briefly, never as the seasonal estimate.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import golden from "../../tests/fixtures/met-no-forecast-singapore.json";
import {
  fetchHomeWeather,
  isRenderableWeather,
  loadModelWeather,
} from "./home-weather";
import { hourlySummary } from "./hourly-summary";
import { currentHourIndex } from "./location-time";
import { synthesizeOpenMeteoInsights, weatherCodeToInfo } from "./weather";
import type { WeatherData } from "./weather";
import { isDegradedBody, workerData } from "./worker-data";

const forecast = golden as unknown as WeatherData;
const FETCHED = new Date("2026-11-02T14:30:00Z");

function respond(provider: string) {
  return {
    ok: true,
    status: 200,
    headers: new Headers({ "X-Weather-Provider": provider }),
    json: async () => golden,
  } as unknown as Response;
}

beforeEach(() => {
  workerData.reset();
});

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("a MET Norway failover forecast", () => {
  it("is renderable: the dashboard's shape check passes", () => {
    expect(isRenderableWeather(forecast)).toBe(true);
    expect(typeof forecast.current.temperature_2m).toBe("number");
    expect(forecast.utc_offset_seconds).toBe(28800);
  });

  it("keeps every hourly and daily array the same length as its time axis", () => {
    for (const block of [forecast.hourly, forecast.daily]) {
      const { time, ...rest } = block as unknown as Record<string, unknown[]>;
      for (const [name, values] of Object.entries(rest)) {
        expect(values, name).toHaveLength(time.length);
      }
    }
  });

  it("only uses weather codes the app can label", () => {
    const codes = [
      ...forecast.hourly.weather_code,
      ...forecast.daily.weather_code,
      forecast.current.weather_code,
    ];
    expect(codes.length).toBeGreaterThan(0);
    for (const code of codes) {
      expect(weatherCodeToInfo(code).label, String(code)).not.toBe("Unknown");
    }
  });

  it("feeds the helpers the page runs on it", () => {
    const start = currentHourIndex(
      forecast.hourly.time,
      forecast.utc_offset_seconds ?? 0,
      FETCHED,
    );
    expect(start).toBe(0);
    expect(forecast.hourly.time[start]).toBe("2026-11-02T22:00");
    // The one-sentence outlook on the Conditions card.
    expect(
      hourlySummary(forecast.hourly, start, forecast.utc_offset_seconds),
    ).toEqual(expect.any(String));
    // The insights the activity rules read, from the same payload.
    const insights = synthesizeOpenMeteoInsights(forecast, FETCHED);
    expect(insights.windSpeed).toBe(5.8);
    expect(insights.visibility).toBeUndefined();
  });

  it("says what it is and is not", () => {
    const baseline = (
      forecast as unknown as { baseline: Record<string, unknown> }
    ).baseline;
    expect(baseline).toMatchObject({
      provider: "met-no",
      blend: false,
      reason: "failover",
      source: "MET Norway",
    });
  });

  it("is not the seasonal estimate and not a degraded body", () => {
    expect(isDegradedBody(golden)).toBe(false);
  });
});

describe("the app reads the met-no provider as a live forecast", () => {
  it("the home page does not call it the seasonal estimate", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn(async () => respond("met-no")),
    );
    const { weather, usingFallback } = await fetchHomeWeather(1.444, 103.824);
    expect(usingFallback).toBe(false);
    expect(weather.current.temperature_2m).toBe(25);
  });

  it("the dashboard fetch is live, and a picked model is not marked served", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn(async () => respond("met-no")),
    );
    // The blend default: live data, no model swap.
    const blend = await loadModelWeather(1.444, 103.824, "best_match", []);
    expect(blend).toMatchObject({ ok: true, fallback: false, baseline: null });
    // A picked model the Worker could not serve: the page keeps its own seed
    // rather than showing MET Norway's numbers as that model's.
    workerData.reset();
    const picked = await loadModelWeather(1.444, 103.824, "ecmwf_ifs", [
      "ecmwf_ifs",
    ]);
    expect(picked).toMatchObject({ ok: true, fallback: false, baseline: null });
  });

  it("is remembered for the route's time, like any live answer", async () => {
    const fetchMock = vi.fn(async () => respond("met-no"));
    vi.stubGlobal("fetch", fetchMock);
    await fetchHomeWeather(1.444, 103.824);
    await fetchHomeWeather(1.444, 103.824);
    expect(fetchMock).toHaveBeenCalledTimes(1);
  });
});
